-- Oracle-style schema excerpt (study example, not executed here)
CREATE TABLE salespeople (
  snum NUMBER(4) PRIMARY KEY, sname VARCHAR2(20),
  city VARCHAR2(15), comm NUMBER(5,2)
);

SELECT c.cname, s.sname
FROM customer c JOIN salespeople s ON s.snum = c.snum;

-- Highest order per customer
SELECT cnum, MAX(amt) FROM orders GROUP BY cnum;

